            continue
        for c, value in enumerate(row):
            if value != 4:
                continue
            dist = abs(line - r)
            step = -1 if r < line else 1
            # The 4 marks the depth of a widening triangle, whose tip is adjacent to the divider.
            for k in range(dist + 1):
                rr = line + step * (k + 1)
                if not (0 <= rr < h):
                    continue
                radius = k
                for cc in range(c - radius, c + radius + 1):
                    if 0 <= cc < w:
                        out[rr][cc] = 4
    return out
