def transform(grid):
    h, w = len(grid), len(grid[0])
    wall = next(r for r, row in enumerate(grid) if row and all(v == 2 for v in row))
    out = [[0 for _ in range(w)] for _ in range(h)]
    out[wall] = grid[wall][:]
    # The 4s fall one cell down; those that land immediately above the wall fan out diagonally.
    for r in range(h):
        for c in range(w):
